<?php
declare(strict_types=1);require_once dirname(__DIR__,2).'/config/database.php';require_once dirname(__DIR__,2).'/includes/auth.php';requireRole(1,4);$s=$pdo->query('SELECT u.nama_unit,COUNT(a.arsip_id) jumlah FROM unit_kerja u LEFT JOIN arsip a ON a.unit_id=u.unit_id GROUP BY u.unit_id,u.nama_unit ORDER BY u.nama_unit');$units=$s->fetchAll();$s=$pdo->prepare('SELECT a.no_registrasi,a.no_surat,a.perihal,a.tanggal_surat,a.status_arsip,u.nama_unit,j.nama_jenis,COALESCE(k.nama_klasifikasi,\'-\') nama_klasifikasi FROM arsip a JOIN unit_kerja u ON u.unit_id=a.unit_id JOIN jenis_surat j ON j.jenis_surat_id=a.jenis_surat_id LEFT JOIN klasifikasi_arsip k ON k.klasifikasi_id=a.klasifikasi_id ORDER BY a.created_at DESC');$s->execute();$items=$s->fetchAll();?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><?php require dirname(__DIR__,2).'/includes/favicon.php';?><link rel="stylesheet" href="assets/css/auth.css"><title>Laporan Arsip</title></head><body class="dashboard-body"><main class="admin-content"><section class="panel"><h2>Laporan Arsip</h2><div class="table-wrap"><table><thead><tr><th>Unit</th><th>Jumlah Arsip</th></tr></thead><tbody><?php foreach($units as $x):?><tr><td><?=e($x['nama_unit'])?></td><td><?=(int)$x['jumlah']?></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel user-list"><h2>Monitoring Arsip</h2><div class="table-wrap"><table><thead><tr><th>Registrasi</th><th>Surat</th><th>Perihal</th><th>Unit</th><th>Jenis</th><th>Klasifikasi</th><th>Status</th></tr></thead><tbody><?php foreach($items as $x):?><tr><td><?=e($x['no_registrasi'])?></td><td><?=e($x['no_surat'])?></td><td><?=e($x['perihal'])?></td><td><?=e($x['nama_unit'])?></td><td><?=e($x['nama_jenis'])?></td><td><?=e($x['nama_klasifikasi'])?></td><td><?=e($x['status_arsip'])?></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="7">Belum ada data arsip.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>